"use strict";(self.webpackChunkblog=self.webpackChunkblog||[]).push([[130],{7735:r=>{r.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2024/12/30/cunstomRef","metadata":{"permalink":"/blog/2024/12/30/cunstomRef","source":"@site/blog/2024-12-30/cunstomRef.md","title":"CustomRef","description":"vue3 \u63d0\u4f9b\u7684\u5bf9 Ref \u7684\u81ea\u5b9a\u4e49 api\uff0c\u65b9\u4fbf\u5b9e\u73b0\u5728\u53cc\u5411\u7ed1\u5b9a\u65f6\u8fdb\u884c\u5176\u4ed6\u64cd\u4f5c\u7684\u529f\u80fd","date":"2024-12-30T00:00:00.000Z","tags":[],"readingTime":2.645,"hasTruncateMarker":false,"authors":[],"frontMatter":{"sidebar_position":1,"sidebar_label":"CustomRef","title":"CustomRef"},"unlisted":false},"content":"vue3 \u63d0\u4f9b\u7684\u5bf9 Ref \u7684\u81ea\u5b9a\u4e49 api\uff0c\u65b9\u4fbf\u5b9e\u73b0\u5728\u53cc\u5411\u7ed1\u5b9a\u65f6\u8fdb\u884c\u5176\u4ed6\u64cd\u4f5c\u7684\u529f\u80fd\\r\\n\\r\\n\u521b\u5efa\u4e00\u4e2a\u81ea\u5b9a\u4e49\u7684 ref\uff0c\u663e\u5f0f\u58f0\u660e\u5bf9\u5176\u4f9d\u8d56\u8ffd\u8e2a\u548c\u66f4\u65b0\u89e6\u53d1\u7684\u63a7\u5236\u65b9\u5f0f\u3002\\r\\n\\r\\n## \u4ee5\u5e38\u89c1\u7684\u65b9\u5f0f\u5b9e\u73b0\u9632\u6296\\r\\n\\r\\n\u8f93\u5165\u6846\u8f93\u5165\u503c\uff0c\u7ed1\u5b9a input \u65b9\u6cd5\u5bf9 text \u8fdb\u884c\u66f4\u65b0\uff0cinput change \u65b9\u6cd5\u4e2d setTimeout \u5ef6\u65f6 1 \u79d2\u8d4b\u503c\\r\\n\\r\\n```vue\\r\\n<template>\\r\\n  <div>\\r\\n    <input type=\\"text\\" @input=\\"inputChange\\" />\\r\\n    <div>{{ text }}</div>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { ref } from \\"vue\\";\\r\\n\\r\\nconst text = ref(\\"\\");\\r\\nlet timer;\\r\\n\\r\\nconst inputChange = (e) => {\\r\\n  clearTimeout(timer);\\r\\n  timer = setTimeout(() => {\\r\\n    text.value = e.target.value;\\r\\n  }, 1000);\\r\\n};\\r\\n<\/script>\\r\\n\\r\\n<style lang=\\"scss\\" scoped></style>\\r\\n```\\r\\n\\r\\n\u5982\u679c\u4f7f\u7528 lodash \u7684 debounce \u51fd\u6570\u53ef\u4ee5\u8fd9\u6837\u5b9e\u73b0\\r\\n\\r\\n```vue\\r\\n<template>\\r\\n  <div>\\r\\n    <input type=\\"text\\" @input=\\"debounceInput\\" />\\r\\n    <div>{{ text }}</div>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { ref } from \\"vue\\";\\r\\nimport { debounce } from \\"lodash\\";\\r\\n\\r\\nconst text = ref(\\"\\");\\r\\n\\r\\nconst inputChange = (e) => {\\r\\n  text.value = e.target.value;\\r\\n};\\r\\n\\r\\nconst debounceInput = debounce(inputChange, 1000);\\r\\n<\/script>\\r\\n\\r\\n<style lang=\\"scss\\" scoped></style>\\r\\n```\\r\\n\\r\\n## \u4ee5\u81ea\u5b9a\u4e49 Ref \u5b9e\u73b0\u9632\u6296\\r\\n\\r\\n```javascript\\r\\n// customRef.js\\r\\nimport { customRef } from \\"vue\\";\\r\\n\\r\\nconst debounceRef = (value, delay = 1000) =>\\r\\n  customRef((track, trigger) => {\\r\\n    let timer;\\r\\n    return {\\r\\n      get() {\\r\\n        track();\\r\\n        return value;\\r\\n      },\\r\\n      set(newValue) {\\r\\n        clearTimeout(timer);\\r\\n        timer = setTimeout(() => {\\r\\n          value = newValue;\\r\\n          trigger();\\r\\n        }, delay);\\r\\n      },\\r\\n    };\\r\\n  });\\r\\n\\r\\nexport default debounceRef;\\r\\n```\\r\\n\\r\\n```\\r\\n// vue\\r\\n<template>\\r\\n  <div>\\r\\n    <input type=\\"text\\" v-model=\\"text\\" />\\r\\n    <div>{{ text }}</div>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport debounceRef from \\"../custom/debounceRef\\";\\r\\n\\r\\nconst text = debounceRef(\\"\\");\\r\\n<\/script>\\r\\n\\r\\n<style lang=\\"scss\\" scoped></style>\\r\\n\\r\\n```\\r\\n\\r\\n\u4ee3\u7801\u89e3\u91ca\uff1a\\r\\n\\r\\ncustomRef \u63a5\u53d7\u4e00\u4e2a\u5de5\u5382\u51fd\u6570\uff0c\u5165\u53c2\u662f trace \u548c trigger\uff0ctrace \u8868\u793a\u6536\u96c6\u53d8\u91cf\u7684\u4f9d\u8d56\uff0ctrigger \u8868\u793a\u89e6\u53d1\u6a21\u677f\u7684\u66f4\u65b0\uff0c\u628a\u4e0a\u9762\u7684\u4ee3\u7801\u62c6\u6210\u4e24\u90e8\u5206\u770b,customRef \u4ee3\u7801\u548c ref \u7684\u903b\u8f91\u57fa\u672c\u4e00\u6837, debounce \u4ee3\u7801\u63a5\u53d7\u4e24\u4e2a\u53c2\u6570 value\uff0cdelay\uff0c\u5728 value \u7684 set \u65b9\u6cd5\u4e2d\u8bbe\u7f6e aetTimeout,\u5ef6\u65f6 delay\uff08ms\uff09\uff0c\u4ece\u800c\u5b9e\u73b0\u9632\u6296\uff0ccustomRef \u7684\u4f7f\u7528\u65b9\u6cd5\u8ddf ref \u4e00\u6837\uff0c\u76f4\u63a5\u4f7f\u7528 v-model \u7ed1\u5b9a customeRef \u5c31\u53ef\u4ee5,\u51cf\u5c11\u4e86\u4ee3\u7801\u91cf\u3002\\r\\n\\r\\n```javascript\\r\\ncustomRef((track, trigger) => {\\r\\n  return {\\r\\n    get value() {\\r\\n      // \u4f9d\u8d56\u6536\u96c6\\r\\n      track();\\r\\n      return value;\\r\\n    },\\r\\n    set value(newValue) {\\r\\n      value = newValue;\\r\\n      // \u89e6\u53d1\u66f4\u65b0\\r\\n      trigger();\\r\\n    },\\r\\n  };\\r\\n});\\r\\n```\\r\\n\\r\\n## \u603b\u7ed3\\r\\n\\r\\ncustomeRef \u672c\u8d28\u4e0a\u662f\u5bf9 trace\uff0ctrigger \u4e24\u4e2a\u65b9\u6cd5\u7684\u8c03\u7528\u65f6\u673a\u81ea\u5b9a\u4e49\uff0c\u5bf9 trigger \u5ef6\u65f6\u66f4\u65b0\u5c31\u662f\u9632\u6296\uff0c\u5982\u679c\u4e0d\u5bf9 trace \u548c trigger \u4fee\u6539\uff0c\u6548\u679c\u5c31\u548c ref \u662f\u4e00\u6837\u7684\u3002\u901a\u8fc7 customRef,\u53ef\u4ee5\u5bf9\u5f88\u591a\u91cd\u590d\u7684\u4ee3\u7801\u8fdb\u884c\u590d\u7528\uff0c\u51cf\u5c11\u4ee3\u7801\u7ef4\u62a4\u3002"}]}}')}}]);